INSERT INTO "passes" ("event_id", "code", "name", "audience", "summary", "description", "price_minor", "currency_code", "allocation", "eligibility", "inclusion_set_id", "offers", "booking_route", "note", "is_published", "is_sold_out", "display_order") VALUES ('devfest-2026', 'liftoff', 'LiftOff Pass', 'Early community access', 'Sessions, workshops, lunch and refreshments, DevFest Goodies, and Community, Expert and Exhibit Lounge access. Workshop seats are first come, first served.', 'Full-day access for developers and community members.', 69900, 'INR', 70, '["Open to everyone","Up to 2 tickets per order, with separate details for each attendee"]', 'devfest-2026-standard', NULL, NULL, NULL, 0, 1, 0);
INSERT INTO "passes" ("event_id", "code", "name", "audience", "summary", "description", "price_minor", "currency_code", "allocation", "eligibility", "inclusion_set_id", "offers", "booking_route", "note", "is_published", "is_sold_out", "display_order") VALUES ('devfest-2026', 'observer', 'Observer Pass', 'Sessions only', 'Keynotes and open sessions. No food, refreshments, workshops or DevFest Goodies.', 'Keynotes and open technical sessions only.', NULL, 'INR', 100, '["Open to community walk-ins and session-only attendees"]', 'devfest-2026-observer', NULL, NULL, 'Lunch, tea, refreshments, workshop hall access and DevFest Goodies are not included.', 0, 0, 5);
INSERT INTO "passes" ("event_id", "code", "name", "audience", "summary", "description", "price_minor", "currency_code", "allocation", "eligibility", "inclusion_set_id", "offers", "booking_route", "note", "is_published", "is_sold_out", "display_order") VALUES ('devfest-2026', 'professional', 'Commander Pass', 'Working professionals', 'Sessions, workshops, lunch and refreshments, DevFest Goodies, and Community, Expert and Exhibit Lounge access. Workshop seats are first come, first served.', 'Full-day access for working professionals.', 84900, 'INR', 250, '["Working professionals only, including engineers, architects, tech leads, managers and founders","Students must choose Cadet","Register every attendee with their own details"]', 'devfest-2026-standard', '["5% off with an ambassador code","15% off 6–10 tickets"]', NULL, 'Enter an ambassador code in the Discount / Access Code field for 5% off, or get 15% off 6–10 tickets automatically. Discounts cannot be combined.', 1, 0, 2);
INSERT INTO "passes" ("event_id", "code", "name", "audience", "summary", "description", "price_minor", "currency_code", "allocation", "eligibility", "inclusion_set_id", "offers", "booking_route", "note", "is_published", "is_sold_out", "display_order") VALUES ('devfest-2026', 'student', 'Cadet Pass', 'Students only', 'Sessions, workshops, lunch and refreshments, DevFest Goodies, and Community, Expert and Exhibit Lounge access. Workshop seats are first come, first served. Government photo ID and original student ID required.', 'Full-day access for college and university students.', 84900, 'INR', 200, '["Currently enrolled students only","Add your college, degree and graduation year at checkout","1 ticket per order","Bring your **government photo ID** and **original student ID** to check-in"]', 'devfest-2026-standard', '["5% off with your ambassador code"]', 'ambassador', NULL, 1, 0, 1);
